92	// RegisterJob stores a new job together with its initial history entry, or
93	// returns the existing record. It returns created=true only when a new row was
94	// inserted. A re-registration whose fields differ in value or array order fails
95	// with *JobConflictError; in every failure case existing content is left
96	// untouched.
97	func (s *Store) RegisterJob(ctx context.Context, reg JobRegistration) (job *Job, created bool, err error) {
98		s.writeMu.Lock()
99		defer s.writeMu.Unlock()
100	
101		// A dedicated connection with BEGIN IMMEDIATE takes the write lock up
102		// front: overlapping registrations (including other processes) queue on
103		// busy_timeout and then observe the winner's committed row instead of
104		// failing on a deferred-lock upgrade.
105		conn, err := s.db.Conn(ctx)
106		if err != nil {
107			return nil, false, err
108		}
109		defer conn.Close()
110	
111		if _, err := conn.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
112			return nil, false, err
113		}
114		committed := false
115		defer func() {
116			if !committed {
117				_, _ = conn.ExecContext(context.Background(), "ROLLBACK")
118			}
119		}()
120	
121		var existingType string
122		var participantsJSON, inputRefsJSON string
123		lookupErr := conn.QueryRowContext(ctx,
124			`SELECT computation_type, participants, input_refs FROM jobs WHERE id = ?`,
125			reg.ID,
126		).Scan(&existingType, &participantsJSON, &inputRefsJSON)
127	
128		if lookupErr == nil {
129			var existingParticipants, existingRefs []string
130			if err := json.Unmarshal([]byte(participantsJSON), &existingParticipants); err != nil {
131				return nil, false, err
132			}
133			if err := json.Unmarshal([]byte(inputRefsJSON), &existingRefs); err != nil {
134				return nil, false, err
135			}
136			if existingType != reg.ComputationType ||
137				!equalStrings(existingParticipants, reg.Participants) ||
138				!equalStrings(existingRefs, reg.InputRefs) {
139				return nil, false, &JobConflictError{ID: reg.ID}
140			}
141			job, err := loadJob(ctx, conn, reg.ID)
142			if err != nil {
143				return nil, false, err
144			}
145			if _, err := conn.ExecContext(ctx, "COMMIT"); err != nil {
146				return nil, false, err
147			}
148			committed = true
149			return job, false, nil
150		}
151		if !errors.Is(lookupErr, sql.ErrNoRows) {
152			return nil, false, lookupErr
153		}
154	
155		encodedParticipants, err := json.Marshal(reg.Participants)
156		if err != nil {
157			return nil, false, err
158		}
159		encodedInputRefs, err := json.Marshal(reg.InputRefs)
160		if err != nil {
161			return nil, false, err
162		}
163	
164		if _, err := conn.ExecContext(ctx,
165			`INSERT INTO jobs (id, computation_type, participants, input_refs, stage)
166			 VALUES (?, ?, ?, ?, ?)`,
167			reg.ID, reg.ComputationType, string(encodedParticipants),
168			string(encodedInputRefs), StageRegistered,
169		); err != nil {
170			return nil, false, err
171		}
172		for position, participant := range reg.Participants {
173			if _, err := conn.ExecContext(ctx,
174				`INSERT INTO job_participants (job_id, position, participant)
175				 VALUES (?, ?, ?)`,
176				reg.ID, position, participant,
177			); err != nil {
178				return nil, false, err
179			}
180		}
181		if _, err := conn.ExecContext(ctx,
182			`INSERT INTO job_history (job_id, seq, stage) VALUES (?, 0, ?)`,
183			reg.ID, StageRegistered,
184		); err != nil {
185			return nil, false, err
186		}
187		if _, err := conn.ExecContext(ctx, "COMMIT"); err != nil {
188			return nil, false, err
189		}
190		committed = true
191	
192		return &Job{
193			ID:              reg.ID,
194			ComputationType: reg.ComputationType,
195			Participants:    append([]string(nil), reg.Participants...),
196			InputRefs:       append([]string(nil), reg.InputRefs...),
197			Stage:           StageRegistered,
198			History:         []HistoryEntry{{Stage: StageRegistered}},
199		}, true, nil
