303		if len(jobs) == 0 {
304			return nil
305		}
306	
307		var builder strings.Builder
308		builder.WriteString(`SELECT job_id, stage FROM job_history WHERE job_id IN (`)
309		args := make([]any, len(jobs))
310		for i, job := range jobs {
311			if i > 0 {
312				builder.WriteByte(',')
313			}
314			builder.WriteString("?")
315			args[i] = job.ID
316		}
317		builder.WriteString(`) ORDER BY job_id COLLATE BINARY, seq`)
318	
319		rows, err := q.QueryContext(ctx, builder.String(), args...)
320		if err != nil {
321			return err
322		}
323		defer rows.Close()
324	
325		history := make(map[string][]HistoryEntry, len(jobs))
326		for rows.Next() {
327			var jobID, stage string
328			if err := rows.Scan(&jobID, &stage); err != nil {
329				return err
330			}
331			history[jobID] = append(history[jobID], HistoryEntry{Stage: stage})
332		}
333		if err := rows.Err(); err != nil {
334			return err
335		}
336	
337		for _, job := range jobs {
338			if entries := history[job.ID]; len(entries) > 0 {
339				job.History = entries
340			} else {
341				job.History = []HistoryEntry{}
342			}
343		}
344		return nil
345	}
