359	var schemaStatements = []string{
360		`CREATE TABLE IF NOT EXISTS service_metadata (
361			key   TEXT PRIMARY KEY,
362			value TEXT NOT NULL
363		);`,
364		`CREATE TABLE IF NOT EXISTS jobs (
365			id               TEXT PRIMARY KEY,
366			computation_type TEXT NOT NULL,
367			participants     TEXT NOT NULL,
368			input_refs       TEXT NOT NULL,
369			stage            TEXT NOT NULL
370		);`,
371		`CREATE TABLE IF NOT EXISTS job_participants (
372			job_id      TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
373			position    INTEGER NOT NULL,
374			participant TEXT NOT NULL,
375			PRIMARY KEY (job_id, position)
376		);`,
377		`CREATE TABLE IF NOT EXISTS job_history (
378			job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
379			seq    INTEGER NOT NULL,
380			stage  TEXT NOT NULL,
381			PRIMARY KEY (job_id, seq)
382		);`,
383		`CREATE INDEX IF NOT EXISTS idx_job_participants_participant
384			ON job_participants(participant);`,
