			assertErrorCode(t, rec, "invalid_request")
		})
	}

	list := getJobs(handler, "/jobs")
	var envelope struct {
		Total int `json:"total"`
	}
	json.Unmarshal(list.Body.Bytes(), &envelope)
	if envelope.Total != 0 {
		t.Fatalf("invalid requests wrote data: %s", list.Body.String())
	}
}

