	if len(job.InputRefs) != 2 || job.InputRefs[0] != "ref-a" || job.InputRefs[1] != "ref-b" {
		t.Fatalf("input_refs = %v", job.InputRefs)
	}
	if len(job.History) != 1 || job.History[0].Stage != StageRegistered {
