	reg1 := sampleRegistration()
	reg1.ID = "j1"
	reg1.Participants = []string{"alice", "bob"}
	reg2 := sampleRegistration()
	reg2.ID = "j2"
	reg2.Participants = []string{"carol"}
	for _, reg := range []JobRegistration{reg1, reg2} {
